package com.example.hazardreporting.data.incident.entity

import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey
import com.example.hazardreporting.domain.model.SyncState

/**
 * Room row of the `incidents` table: an incident's summary, its details once they are downloaded,
 * and its sync bookkeeping. Status and priority keep the server's wire values, so a value this app version
 * doesn't know survives being stored
 *
 * @property localId id of the incident on the device, generated by Room
 * @property serverId id of the incident on the server, or null until the server accepts the report
 * @property title short description of the problem
 * @property categoryId id of the incident's category
 * @property severityId id of the incident's severity
 * @property siteId id of the site the incident belongs to
 * @property status the server's status value, e.g. `"in_progress"`
 * @property createdAt when the technician first saved the report, in epoch milliseconds; never changes
 * @property updatedAt when the server last changed the incident, in epoch milliseconds, or null if the server
 * hasn't stored it yet
 * @property description what the technician saw, or null until the details are downloaded
 * @property locationDescription where on the site the problem is, or null until the details are downloaded
 * @property positionLat latitude of the position, or null if there is none or the details aren't downloaded
 * @property positionLng longitude of the position, or null if there is none or the details aren't downloaded
 * @property positionAccuracyM accuracy of the position in metres, or null if there is none
 * or the details aren't downloaded
 * @property priority the server's priority value, e.g. `"urgent"`, or null if it's unset
 * or the details aren't downloaded
 * @property detailsLoaded whether the detail fields hold the incident's details
 * @property syncState whether the incident has a pending change
 * @property localVersion incremented by every local change, so a push can tell whether the row changed meanwhile
 * @property createAttempted whether a POST of the report was ever sent
 * @property statusChangeNoticePending whether a Status Change Notice waits to be dismissed
 *
 * @author Roman Pliskin on 29.10.2026
 */
@Entity(
    tableName = "incidents",
    indices = [Index(value = ["serverId"], unique = true)],
)
data class IncidentEntity(
    @PrimaryKey(autoGenerate = true)
    val localId: Long = 0,
    val serverId: String?,
    val title: String,
    val categoryId: String,
    val severityId: String,
    val siteId: String,
    val status: String,
    val createdAt: Long,
    val updatedAt: Long?,
    val description: String?,
    val locationDescription: String?,
    val positionLat: Double?,
    val positionLng: Double?,
    val positionAccuracyM: Double?,
    val priority: String?,
    val detailsLoaded: Boolean,
    val syncState: SyncState,
    val localVersion: Int,
    val createAttempted: Boolean,
    val statusChangeNoticePending: Boolean,
)
